const $ = (selector) => document.querySelector(selector);
const state = { step: 0, selected: null, revealed: false };
const inserts = DATA.inserts;
const finalTree = DATA.final;

function treeText(tree) {
  if (!tree) return '빈 트리';
  const keys = tree.k.join(' ');
  if (!tree.c) return `[${keys}]`;
  return `[${keys}] / ${tree.c.map(treeText).join(' ')}`;
}

function nodeElement(tree) {
  const wrap = document.createElement('div');
  wrap.className = 'tree-node-wrap';
  const node = document.createElement('div');
  node.className = 'tree-node';
  node.setAttribute('aria-label', `키 ${tree.k.join(', ')}`);
  tree.k.forEach((key) => {
    const part = document.createElement('span');
    part.textContent = key;
    node.appendChild(part);
  });
  wrap.appendChild(node);
  if (tree.c) {
    const children = document.createElement('div');
    children.className = 'tree-children';
    tree.c.forEach((child) => {
      const childWrap = document.createElement('div');
      childWrap.className = 'tree-child';
      childWrap.appendChild(nodeElement(child));
      children.appendChild(childWrap);
    });
    wrap.appendChild(children);
  }
  return wrap;
}

function renderTree(tree, label) {
  const view = $('#treeView');
  view.replaceChildren();
  const root = nodeElement(tree);
  view.appendChild(root);
  $('#treeStateLabel').textContent = label;
  view.setAttribute('aria-label', `현재 트리: ${treeText(tree)}`);
}

function currentTree() {
  if (state.step === 0) return { k: [] };
  const events = inserts[state.step - 1].events;
  return events[events.length - 1].tree;
}

function answerFor(step) {
  const events = inserts[step].events;
  const split = events.find((event) => event.event !== 'placed');
  return split ? String(split.key) : '분할 없음';
}

function choicesFor(step) {
  const answer = answerFor(step);
  if (answer === '분할 없음') return ['분할 없음', '30', '40', '60'];
  const pool = ['분할 없음', '20', '30', '40', '50', '60', '70'];
  return [answer, ...pool.filter((item) => item !== answer).slice(0, 3)];
}

function renderSequence() {
  const target = $('#sequenceKeys');
  target.replaceChildren();
  const keys = inserts.map((item) => item.key);
  keys.forEach((key, index) => {
    const pill = document.createElement('span');
    pill.textContent = key;
    pill.className = index < state.step ? 'done' : index === state.step ? 'active' : '';
    pill.setAttribute('aria-label', `${index + 1}번째 삽입 ${key}`);
    target.appendChild(pill);
  });
}

function renderChoices() {
  const fieldset = $('#choices');
  fieldset.querySelectorAll('.choice').forEach((item) => item.remove());
  if (state.step >= inserts.length) return;
  choicesFor(state.step).forEach((choice, index) => {
    const id = `choice-${state.step}-${index}`;
    const item = document.createElement('div');
    item.className = 'choice';
    item.innerHTML = `<input type="radio" name="prediction" id="${id}" value="${choice}"><label for="${id}">${choice}</label>`;
    item.querySelector('input').addEventListener('change', (event) => {
      state.selected = event.target.value;
      $('#feedback').className = 'feedback';
      $('#feedback').textContent = '선택했습니다. 이제 정답을 확인하세요.';
    });
    fieldset.appendChild(item);
  });
}

function clearFeedback() {
  const feedback = $('#feedback');
  feedback.className = 'feedback';
  feedback.textContent = '';
}

function renderStep() {
  const complete = state.step >= inserts.length;
  $('#stepNumber').textContent = complete ? inserts.length : state.step + 1;
  $('#currentKey').textContent = complete ? '—' : inserts[state.step].key;
  $('#keyToken').textContent = complete ? '완료' : inserts[state.step].key;
  $('#previousButton').disabled = state.step === 0;
  $('#resetButton').disabled = state.step === 0 && !state.revealed;
  $('#revealButton').disabled = complete || state.revealed;
  $('#nextButton').disabled = !state.revealed;
  $('#completion').hidden = !complete;
  renderSequence();
  renderChoices();
  clearFeedback();
  if (complete) {
    renderTree(finalTree, '최종 트리');
    $('#questionHint').textContent = '완주했습니다. 아래에서 검색 trace를 확인하세요.';
    return;
  }
  const label = state.step === 0 ? '시작' : `${state.step}단계까지 반영`;
  renderTree(currentTree(), label);
  $('#questionHint').textContent = answerFor(state.step) === '분할 없음'
    ? '이번 키는 잎에 들어갑니다. 넘침이 없다면 그렇게 선택해 보세요.'
    : '노드가 5개 키로 넘칩니다. 가운데에서 부모로 올라갈 키를 골라 보세요.';
}

function reveal() {
  if (state.step >= inserts.length || state.revealed) return;
  if (state.selected === null) {
    const feedback = $('#feedback');
    feedback.className = 'feedback wrong';
    feedback.textContent = '먼저 선택지를 하나 골라 주세요. 선택하지 않은 것은 오답으로 처리하지 않습니다.';
    return;
  }
  state.revealed = true;
  const answer = answerFor(state.step);
  const feedback = $('#feedback');
  if (state.selected === answer) {
    feedback.className = 'feedback correct';
    feedback.textContent = answer === '분할 없음'
      ? '맞았습니다. 노드가 넘치지 않아 그대로 잎에 자리 잡습니다.'
      : `맞았습니다. 가운데 키 ${answer}가 부모로 올라가고, 양쪽으로 나뉩니다.`;
  } else {
    feedback.className = 'feedback wrong';
    feedback.textContent = answer === '분할 없음'
      ? '아직 분할하지 않습니다. 이번 단계의 노드는 최대 4개를 넘지 않습니다. 다시 생각해 보세요.'
      : `아직 아닙니다. 정답은 가운데 키 ${answer}입니다. 다시 선택하고 확인해 보세요.`;
    state.revealed = false;
    $('#revealButton').disabled = false;
    $('#nextButton').disabled = true;
    return;
  }
  const event = inserts[state.step].events[inserts[state.step].events.length - 1];
  renderTree(event.tree, `정답 반영 · ${event.event}`);
  $('#revealButton').disabled = true;
  $('#nextButton').disabled = false;
}

function next() {
  if (!state.revealed) return;
  state.step += 1;
  state.selected = null;
  state.revealed = false;
  renderStep();
}

function previous() {
  if (state.step === 0) return;
  state.step -= 1;
  state.selected = null;
  state.revealed = false;
  renderStep();
}

function reset() {
  state.step = 0;
  state.selected = null;
  state.revealed = false;
  renderStep();
}

function renderSearches() {
  const target = $('#searchResults');
  DATA.searches.forEach((item) => {
    const card = document.createElement('article');
    card.className = 'search-item';
    card.innerHTML = `<h3>${item.key} <span class="state-label">${item.found ? '찾음' : '없음'}</span></h3>`;
    const path = item.path.map((keys) => `[${keys.join(' ')}]`).join(' → ');
    card.innerHTML += `<p><strong>내려간 경로</strong><br>${path}</p>`;
    card.innerHTML += `<p><strong>비교 순서</strong><br>${item.seen.join(' → ')} (${item.seen.length}번)</p>`;
    target.appendChild(card);
  });
}

$('#revealButton').addEventListener('click', reveal);
$('#nextButton').addEventListener('click', next);
$('#previousButton').addEventListener('click', previous);
$('#resetButton').addEventListener('click', reset);
renderSearches();
renderStep();
